CREATE UNIQUE INDEX "UQ_platform_integrations_github_pending_target" ON "platform_integrations" USING btree ("platform","github_app_type","platform_account_id") WHERE "platform_integrations"."platform" = 'github' AND "platform_integrations"."integration_status" = 'pending' AND "platform_integrations"."platform_installation_id" IS NULL AND "platform_integrations"."platform_account_id" IS NOT NULL;